sql.where:
u.deleted = 0 AND u.role_code = 'CONTRACTOR'
AND u.status = #{status}
AND c.name LIKE '%' + #{companyName} + '%'
AND c.business_number LIKE '%' + #{businessNumber} + '%'
AND CAST(u.created_at AS DATE) >= #{dateFrom}
AND CAST(u.created_at AS DATE) <= #{dateTo}
AND ( u.username LIKE '%' + #{keyword} + '%' OR u.name LIKE '%' + #{keyword} + '%' OR u.email LIKE '%' + #{keyword} + '%' OR c.name LIKE '%' + #{keyword} + '%' OR c.business_number LIKE '%' + #{keyword} + '%' )
